class MiActivacion(nn.Module):
    """Edita esta clase: la fórmula debe usar operaciones de torch.

    Mantén aquí sus constantes y parámetros para conservar la definición.
    Si necesitas parámetros entrenables, decláralos con nn.Parameter.
    """
    def __init__(self):
        super().__init__()
        # Ejemplo opcional: self.beta = nn.Parameter(torch.tensor(1.0))

    def forward(self, x):
        # Activación inicial: ReLU. Sustituye esta expresión por tu fórmula.
        return torch.relu(x)
        # Ejemplo: return x * torch.sigmoid(x) + 0.1 * torch.sin(x)
        # Con beta entrenable: return x * torch.sigmoid(self.beta * x)
